  /* =========================================================================
   * 2. CANVA-STYLE INDEXEDDB VAULT (`thbc_photocard_v2`: uploads + designs)
   * ========================================================================= */
  var idbPromise = null;

  function openPhotoCardDB() {
    if (typeof indexedDB === 'undefined') return Promise.resolve(null);
    if (idbPromise) return idbPromise;
    idbPromise = new Promise(function (resolve) {
      try {
        var req = indexedDB.open(DB_NAME, DB_VERSION);
        req.onupgradeneeded = function () {
          var db = req.result;
          if (!db.objectStoreNames.contains('uploads')) {
            var up = db.createObjectStore('uploads', { keyPath: 'id' });
            up.createIndex('kind', 'kind', { unique: false });
            up.createIndex('updatedAt', 'updatedAt', { unique: false });
          }
          if (!db.objectStoreNames.contains('designs')) {
            var ds = db.createObjectStore('designs', { keyPath: 'id' });
            ds.createIndex('updatedAt', 'updatedAt', { unique: false });
          }
        };
        req.onsuccess = function () { resolve(req.result); };
        req.onerror = function () { resolve(null); };
      } catch (e) {
        resolve(null);
      }
    });
    return idbPromise;
  }

  function dbPut(storeName, record) {
    return openPhotoCardDB().then(function (db) {
      if (!db) return record;
      return new Promise(function (resolve) {
        try {
          var tx = db.transaction(storeName, 'readwrite');
          tx.objectStore(storeName).put(record);
          tx.oncomplete = function () { resolve(record); };
          tx.onerror = function () { resolve(record); };
        } catch (e) {
          resolve(record);
        }
      });
    });
  }

  function dbGet(storeName, id) {
    if (!id) return Promise.resolve(null);
    return openPhotoCardDB().then(function (db) {
      if (!db) return null;
      return new Promise(function (resolve) {
        try {
          var tx = db.transaction(storeName, 'readonly');
          var req = tx.objectStore(storeName).get(id);
          req.onsuccess = function () { resolve(req.result || null); };
          req.onerror = function () { resolve(null); };
        } catch (e) {
          resolve(null);
        }
      });
    });
  }

  function dbDelete(storeName, id) {
    if (!id) return Promise.resolve();
    return openPhotoCardDB().then(function (db) {
      if (!db) return;
      return new Promise(function (resolve) {
        try {
          var tx = db.transaction(storeName, 'readwrite');
          tx.objectStore(storeName).delete(id);
          tx.oncomplete = function () { resolve(); };
          tx.onerror = function () { resolve(); };
        } catch (e) {
          resolve();
        }
      });
    });
  }

  function dbGetAll(storeName) {
    return openPhotoCardDB().then(function (db) {
      if (!db) return [];
      return new Promise(function (resolve) {
        try {
          var tx = db.transaction(storeName, 'readonly');
          var req = tx.objectStore(storeName).getAll();
          req.onsuccess = function () {
            var rows = req.result || [];
            rows.sort(function (a, b) { return (b.updatedAt || 0) - (a.updatedAt || 0); });
            resolve(rows);
          };
          req.onerror = function () { resolve([]); };
        } catch (e) {
          resolve([]);
        }
      });
    });
  }

  function loadImageFromBlobOrUrl(src) {
    return new Promise(function (resolve, reject) {
      if (!src) { reject(new Error('empty')); return; }
      var revoke = false;
      var url = src;
      if (src instanceof Blob) {
        url = URL.createObjectURL(src);
        revoke = true;
      }
      var img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = function () {
        if (revoke) {
          setTimeout(function () { URL.revokeObjectURL(url); }, 2500);
        }
        resolve(img);
      };
      img.onerror = function () {
        if (revoke) URL.revokeObjectURL(url);
        reject(new Error('load failed'));
      };
      img.src = url;
    });
  }

  // Downscales huge camera photos to max 2048px for ultra-fast storage & generates a crisp 200px thumbnail
  function processFileToAsset(file, kind) {
    return loadImageFromBlobOrUrl(file).then(function (img) {
      var nw = img.naturalWidth || img.width || 512;
      var nh = img.naturalHeight || img.height || 512;
      var maxDim = kind === 'logo' ? 900 : 2048;
      var scale = Math.min(1, maxDim / Math.max(nw, nh));
      var outW = Math.max(1, Math.round(nw * scale));
      var outH = Math.max(1, Math.round(nh * scale));

      var workCanvas = document.createElement('canvas');
      workCanvas.width = outW;
      workCanvas.height = outH;
      var wctx = workCanvas.getContext('2d');
      wctx.drawImage(img, 0, 0, outW, outH);

      var preserveAlpha = kind === 'logo' || /png|svg|webp|gif/i.test(file.type || '');
      var outMime = preserveAlpha ? 'image/png' : 'image/jpeg';

      // Build compact 200px thumbnail for Canva gallery grid
      var tMax = 200;
      var tScale = Math.min(1, tMax / Math.max(outW, outH));
      var tw = Math.max(1, Math.round(outW * tScale));
      var th = Math.max(1, Math.round(outH * tScale));
      var tCanvas = document.createElement('canvas');
      tCanvas.width = tw;
      tCanvas.height = th;
      tCanvas.getContext('2d').drawImage(workCanvas, 0, 0, tw, th);
      var thumbDataUrl = tCanvas.toDataURL(preserveAlpha ? 'image/png' : 'image/jpeg', 0.82);

      return new Promise(function (resolve) {
        workCanvas.toBlob(function (blob) {
          var finalBlob = blob || file;
          var fileSig = kind + ':' + (file.name || 'asset') + ':' + (file.size || 0);
          resolve({
            img: img,
            record: {
              id: uid(kind),
              kind: kind,
              name: String(file.name || (kind === 'logo' ? 'Logo' : 'Photo')).slice(0, 80),
              mime: outMime,
              width: outW,
              height: outH,
              blob: finalBlob,
              thumbDataUrl: thumbDataUrl,
              fileSig: fileSig,
              createdAt: Date.now(),
              updatedAt: Date.now()
            }
          });
        }, outMime, 0.9);
      });
    });
  }

  function saveAssetDeduplicated(file, kind) {
    var sig = kind + ':' + (file.name || 'asset') + ':' + (file.size || 0);
    return dbGetAll('uploads').then(function (existing) {
      var match = existing.filter(function (u) { return u.fileSig === sig && u.blob; })[0];
      if (match) {
        match.updatedAt = Date.now();
        return Promise.all([loadImageFromBlobOrUrl(match.blob), dbPut('uploads', match)]).then(function (res) {
          return { img: res[0], record: match };
        });
      }
      return processFileToAsset(file, kind).then(function (res) {
        return dbPut('uploads', res.record).then(function () { return res; });
      });
    });
  }

