  var uploadedCustomFonts = []; // [{ id, family, name, updatedAt }]
  var registeredFontFamilies = {};

  function ensureGoogleFontsLoaded() {
    if (typeof document === 'undefined' || document.getElementById('pcGoogleFontsLink')) return;
    var link = document.createElement('link');
    link.id = 'pcGoogleFontsLink';
    link.rel = 'stylesheet';
    link.href = 'https://fonts.googleapis.com/css2?family=Anek+Bangla:wght@500;700;800&family=Anton&family=Atma:wght@600;700&family=Baloo+Da+2:wght@600;700;800&family=Bebas+Neue&family=Dancing+Script:wght@700&family=Galada&family=Hind+Siliguri:wght@500;600;700&family=Inter:wght@500;700;800;900&family=JetBrains+Mono:wght@600;700&family=Merriweather:ital,wght@0,700;1,700&family=Mina:wght@700&family=Montserrat:ital,wght@0,600;0,700;0,800;0,900;1,700&family=Noto+Sans+Bengali:wght@500;700;800&family=Noto+Serif+Bengali:wght@600;700;800&family=Oswald:wght@600;700&family=Pacifico&family=Playfair+Display:ital,wght@0,700;0,800;1,700&family=Plus+Jakarta+Sans:wght@600;700;800&family=Poppins:ital,wght@0,600;0,700;0,800;1,600&family=Raleway:ital,wght@0,600;0,700;0,800;1,700&family=Roboto+Condensed:wght@700;800&family=Tiro+Bangla:ital@0;1&display=swap';
    document.head.appendChild(link);
  }

  function registerCustomFontRecord(rec) {
    if (!rec || !rec.blob || !rec.family || typeof FontFace === 'undefined') return Promise.resolve(false);
    if (registeredFontFamilies[rec.family]) return Promise.resolve(true);
    return rec.blob.arrayBuffer().then(function (buf) {
      var face = new FontFace(rec.family, buf);
      return face.load().then(function (loaded) {
        document.fonts.add(loaded);
        registeredFontFamilies[rec.family] = true;
        return true;
      });
    }).catch(function () {
      return false;
    });
  }

  function loadAllCustomFontsFromDB() {
    return dbGetAll('uploads').then(function (items) {
      var fontRows = (items || []).filter(function (x) { return x && x.kind === 'font' && x.blob; });
      uploadedCustomFonts = fontRows.map(function (r) {
        return { id: r.id, family: r.family, name: r.name || r.family, updatedAt: r.updatedAt || 0 };
      });
      return Promise.all(fontRows.map(registerCustomFontRecord)).then(function () {
        renderFontDrawerList();
      });
    });
  }

  function getStudioLang() {
    var htmlLang = typeof document !== 'undefined' && document.documentElement && typeof document.documentElement.getAttribute === 'function' ? document.documentElement.getAttribute('data-lang') : null;
    if (htmlLang === 'en' || htmlLang === 'bn') return htmlLang;
    try {
      var saved = localStorage.getItem('thbc-lang');
      if (saved === 'en' || saved === 'bn') return saved;
    } catch (e) {}
    return 'bn';
  }

  function isEn() {
    return getStudioLang() === 'en';
  }

  function tr(bn, en) {
    return isEn() ? (en || bn) : bn;
  }

  function syncStudioLangUI() {
    var pane = $('#img-pane-photo-card');
    if (!pane) return;
    var lang = getStudioLang();
    $$('#pcLangSwitchGroup [data-set-lang]', pane).forEach(function (btn) {
      btn.setAttribute('aria-pressed', btn.getAttribute('data-set-lang') === lang ? 'true' : 'false');
    });
    $$('[data-i18n-bn]', pane).forEach(function (el) {
      var target = lang === 'en' ? el.getAttribute('data-i18n-en') : el.getAttribute('data-i18n-bn');
      if (target) el.textContent = target;
    });
    $$('[data-i18n-placeholder-bn]', pane).forEach(function (el) {
      var ph = lang === 'en' ? el.getAttribute('data-i18n-placeholder-en') : el.getAttribute('data-i18n-placeholder-bn');
      if (ph) el.setAttribute('placeholder', ph);
    });
    if (!state.userEditedTitle && (state.designTitle === 'নতুন ফটোকার্ড ডিজাইন' || state.designTitle === 'Untitled Photo Card')) {
      state.designTitle = lang === 'en' ? 'Untitled Photo Card' : 'নতুন ফটোকার্ড ডিজাইন';
      var tInp = $('#pcDesignTitleInput', pane);
      if (tInp && document.activeElement !== tInp) tInp.value = state.designTitle;
    }
  }

