  // In-memory cache: url -> { status: 'loading'|'loaded'|'error', img: HTMLImageElement|null }
  var stockPhotoCache = {};

  function getStockPhotoSpec(templateId, categoryId, isSecondary) {
    var isSec = (isSecondary === true || isSecondary === 'slot-2' || isSecondary === 2 || isSecondary === 'secondary');
    if (isSec && templateId === 'factcheck-dual') {
      return STOCK_PHOTO_REGISTRY['factcheck-dual-verified'] || STOCK_PHOTO_REGISTRY['factcheck'];
    }
    if (templateId && Object.prototype.hasOwnProperty.call(STOCK_PHOTO_REGISTRY, templateId)) {
      return STOCK_PHOTO_REGISTRY[templateId];
    }
    if (categoryId && Object.prototype.hasOwnProperty.call(STOCK_PHOTO_REGISTRY, categoryId)) {
      return STOCK_PHOTO_REGISTRY[categoryId];
    }
    return STOCK_PHOTO_REGISTRY['default'];
  }

  var stockPhotoRefreshTimer = null;

  function invalidateAndRefreshStockUrl(loadedUrl) {
    if (typeof document !== 'undefined') {
      var pane = $('#img-pane-photo-card');
      if (pane) {
        $$('.pc-page-canvas', pane).forEach(function (cv) {
          if (cv && cv.dataset) cv.dataset.painted = '';
        });
      }
      var tplIds = Object.keys(TEMPLATE_META);
      for (var i = 0; i < tplIds.length; i++) {
        var tid = tplIds[i];
        var m = TEMPLATE_META[tid];
        var spec1 = getStockPhotoSpec(tid, m && m.cat, false);
        var spec2 = getStockPhotoSpec(tid, m && m.cat, true);
        if ((spec1 && spec1.url === loadedUrl) || (spec2 && spec2.url === loadedUrl)) {
          delete tplThumbCache[tid];
          if ($$('[data-tpl-thumb="' + tid + '"]').length > 0 && typeof renderSingleTemplateThumb === 'function') {
            var newThumb = renderSingleTemplateThumb(tid);
            applyThumbToDom(tid, newThumb);
          }
        }
      }
    }
    scheduleStockPhotoVisualRefresh();
  }

  function scheduleStockPhotoVisualRefresh() {
    if (stockPhotoRefreshTimer) clearTimeout(stockPhotoRefreshTimer);
    stockPhotoRefreshTimer = setTimeout(function () {
      stockPhotoRefreshTimer = null;
      tplThumbCache = {};
      if (typeof generateAllTemplateThumbnails === 'function') {
        generateAllTemplateThumbnails(true);
      }
      if (typeof document !== 'undefined') {
        var pane = $('#img-pane-photo-card');
        if (pane) {
          $$('.pc-page-canvas', pane).forEach(function (cv) {
            if (cv && cv.dataset) cv.dataset.painted = '';
          });
        }
      }
      if (typeof renderPagesUi === 'function') renderPagesUi();
      if (typeof renderNow === 'function') renderNow();
    }, 80);
  }

  function preloadStockPhoto(url) {
    if (!url || stockPhotoCache[url]) return;
    stockPhotoCache[url] = { status: 'loading', img: null };

    if (typeof Image === 'undefined') return;
    var img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = function () {
      stockPhotoCache[url] = { status: 'loaded', img: img };
      requestRender(true);
      invalidateAndRefreshStockUrl(url);
    };
    img.onerror = function () {
      stockPhotoCache[url] = { status: 'error', img: null };
    };
    img.src = url;
  }

