    var shareBtn = $('#pcShareCardBtn', pane);
    var shareClose = $('#pcShareCloseBtn', pane);
    var copyLink = $('#pcCopyLinkBtn', pane);
    var whatsAppBtn = $('#pcShareWhatsAppBtn', pane);
    var copyImgBtn = $('#pcShareCopyImageBtn', pane);
    var nativeBtn = $('#pcShareNativeBtn', pane);
    var qPngBtn = $('#pcQuickDownloadPngBtn', pane);
    var qJpgBtn = $('#pcQuickDownloadJpgBtn', pane);
    var qPdfBtn = $('#pcShareDownloadPdf', pane);

    if (pngBtn) pngBtn.addEventListener('click', function () { exportCardFile('image/png', 'png'); });
    if (jpgBtn) jpgBtn.addEventListener('click', function () { exportCardFile('image/jpeg', 'jpg'); });
